# I will now get detailed info for each song in all playlists using `show_song` API.
# I will store song details in a dictionary keyed by song_id to avoid duplicate calls for the same song.

song_details = {}
for playlist in all_playlists:
    for song_id in playlist['song_ids']:
        if song_id not in song_details:
            song_info = apis.spotify.show_song(song_id=song_id)
            song_details[song_id] = song_info

print(song_details)  # To verify the song details collected.

# I have detailed song info for all songs in playlists.
# Now I will create a set of old songs from the old songs list for quick matching.
# The old songs list format is "Title by Artist1, Artist2"
# I will create a set of strings in the same format from the song details to compare.

old_songs_set = set(old_songs)  # old_songs was extracted from the file earlier

def format_song_for_matching(song):
    title = song['title']
    artists = ", ".join(artist['name'] for artist in song['artists'])
    return f"{title} by {artists}"

# Create a mapping of song_id to formatted string
song_id_to_formatted = {song_id: format_song_for_matching(song) for song_id, song in song_details.items()}

# Identify songs to remove from each playlist (those that match old songs)
songs_to_remove_by_playlist = {}
for playlist in all_playlists:
    playlist_id = playlist['playlist_id']
    songs_to_remove = []
    for song_id in playlist['song_ids']:
        formatted = song_id_to_formatted.get(song_id)
        if formatted in old_songs_set:
            songs_to_remove.append(song_id)
    if songs_to_remove:
        songs_to_remove_by_playlist[playlist_id] = songs_to_remove

print(songs_to_remove_by_playlist)  # To verify which songs to remove from which playlists.
